<template>
	<view>
		<view class="box">
			<view class="box_title">
				营业日
			</view>
			<view class="day_box">
				<view class="day_item" @click="setShow(index)" :class="item.is_show?'active':''"
					v-for="(item,index) in dayList">
					<view class="day_name">
						{{item.name}}
					</view>
					<view class="day_arrow" v-if="item.is_show">
						<u-icon name="arrow-down" color="#036045" size="16"></u-icon>
					</view>
					<view class="day_arrow" v-else>
						<u-icon name="arrow-down" color="#B6BCC9" size="16"></u-icon>
					</view>
				</view>
			</view>
			<view class="time_box mt-36">
				<span>营业时间段:</span>
				<view class="">
					<input type="text" v-if="timeShow" />
					<image @click="show=true" class="mt-2" v-else src="../static/cicon18.png" mode="aspectFill"></image>
				</view>
			</view>
		</view>
		<view class="btns">
			确认
		</view>
		<u-picker :show="show" :columns="columns"></u-picker>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				show: false,
				columns: [
					['00:00', '01:00', '02:00'],
					['03:00', '04:00', '05:00']
				],
				timeShow: false,
				dayList: [{
						name: "周一",
						is_show: false,
						id: 0
					},
					{
						name: "周二",
						is_show: false,
						id: 1
					},
					{
						name: "周三",
						is_show: false,
						id: 2
					},
					{
						name: "周四",
						is_show: false,
						id: 3
					},
					{
						name: "周五",
						is_show: false,
						id: 4
					},
					{
						name: "周六",
						is_show: false,
						id: 5
					},
					{
						name: "周日",
						is_show: false,
						id: 6
					},

				]
			};
		},
		methods: {
			setShow(index) {
				this.dayList[index].is_show = !this.dayList[index].is_show
			}
		}
	}
</script>

<style lang="scss">
	page {
		background: #FAFAFA;
		padding: 24rpx;
		box-sizing: border-box;
	}

	.box {
		width: 701rpx;
		background: #FFFFFF;
		border-radius: 12rpx 12rpx 12rpx 12rpx;
		padding: 40rpx;
		box-sizing: border-box;
		margin-bottom: 60rpx;

		.box_title {
			font-weight: 600;
			font-size: 33rpx;
			color: #3D3D3D;
			margin-bottom: 20rpx;
		}

		.time_box {
			width: 632rpx;
			height: 98rpx;
			background: #F4F6F8;
			padding: 36rpx 20rpx;
			box-sizing: border-box;
			display: flex;
			align-items: center;
			justify-content: space-between;
			font-size: 28rpx;
			color: #3D3D3D;
			font-weight: 600;

			image {
				width: 36rpx;
				height: 36rpx;
			}
		}
	}

	.active {
		background-color: #E1FFF6 !important;
		color: #036045 !important;
	}

	.day_box {
		display: grid;
		grid-template-columns: repeat(5, 106rpx);
		row-gap: 16rpx;
		justify-content: space-between;

		.day_item {
			padding: 24rpx;
			box-sizing: border-box;
			text-align: center;
			width: 106rpx;
			height: 98rpx;
			background: #EEF1F4;
			border-radius: 4rpx 4rpx 4rpx 4rpx;
			display: flex;
			flex-direction: column;
			justify-content: center;
			font-size: 28rpx;
			color: #878FA0;
			font-weight: 600;


			.day_arrow {
				margin: 10rpx auto 0;
			}
		}
	}

	.btns {
		height: 85rpx;
		background: #036045;
		border-radius: 16rpx 16rpx 16rpx 16rpx;
		font-weight: 400;
		font-size: 28rpx;
		color: #FFFFFF;
		line-height: 85rpx;
		text-align: center;
	}
</style>